package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonRepository;

/** The audit line for a saved claim: the event, sheet and user, then the person's name, the amount
 *  (two decimals, as shown) and the date (yyyy-mm-dd); then, when the claim has a number, number=. */
final class ClaimAudit {
    private ClaimAudit() {
    }

    static String line(String event, Claim claim, String user, PersonRepository people) {
        Integer number = claim.getNumber();
        String person = people.findById(claim.getPersonId()).orElseThrow().getName();
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + (user == null ? "" : user.trim())
                + " person=" + person + " amount=" + shown.amount() + " date=" + shown.date()
                + (number == null ? "" : " number=" + number);
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { importPeople, peopleKey } from './people';
import type { ImportResult } from './people';

// Import people pasted as lines of name,grade. The server checks every line first; when any is bad
// nothing is imported and each bad line is marked by its number, otherwise the counts added and
// updated (a name already on the sheet updates that person's grade) are shown.
function ImportPeople() {
  const [sheet] = useCurrentSheet();
  const [user] = useCurrentUser();
  const [text, setText] = useState('');
  const [result, setResult] = useState<ImportResult | null>(null);
  const [failed, setFailed] = useState(false);
  const queryClient = useQueryClient();
  const once = useSubmitOnce();

  const run = useMutation({
    mutationFn: (input: string) => importPeople(sheet!, user, input),
    onSuccess: async (r) => {
      setResult(r);
      setText('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet!) });
    },
    onError: (e) => {
      const body = e instanceof HttpError ? (e.body as ImportResult | undefined) : undefined;
      if (body && Array.isArray(body.errors)) setResult({ added: 0, updated: 0, errors: body.errors });
      else setFailed(true);
    },
  });

  if (!sheet) return null;

  const clear = () => {
    setResult(null);
    setFailed(false);
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    clear();
    once(() => run.mutateAsync(text));
  };

  return (
    <section data-testid="import">
      <h2>Import people</h2>
      <form data-testid="import-form" onSubmit={submit}>
        <textarea
          data-testid="import-text"
          placeholder="name,grade — one person per line"
          rows={4}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            clear();
          }}
        />
        <button type="submit" data-testid="import-submit" disabled={run.isPending}>
          Import
        </button>
      </form>
      {result && (
        <p>
          Added <span data-testid="import-added">{result.added}</span>, updated{' '}
          <span data-testid="import-updated">{result.updated}</span>
          {result.errors.length > 0 && <> — nothing was imported; fix these lines:</>}
        </p>
      )}
      {result && result.errors.length > 0 && (
        <ul>
          {result.errors.map((n) => (
            <li key={n} data-testid={`import-error-${n}`}>
              Line {n}: a name is required, not repeated in the paste, with a grade of A, B or C.
            </li>
          ))}
        </ul>
      )}
      {failed && <span data-testid="import-failed">The import could not be made.</span>}
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 15, Component: ImportPeople });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a caller tell one refusal from another (e.g. 409 Conflict). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number, readonly body?: unknown) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    // A refusal may explain itself in a JSON body (e.g. which lines of an import were bad).
    const body: unknown = await res.json().catch(() => undefined);
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, body);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// `user` is the signed-in name, sent as X-User so the server can record who made a change.
const headers = (user?: string): Record<string, string> => ({
  'Content-Type': 'application/json',
  ...(user ? { 'X-User': user } : {}),
});

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: headers(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: headers(user),
    body: JSON.stringify(body),
  });
}

